#include <ESP8266WiFi.h>
#include <ESP8266WebServer.h>
#include <DNSServer.h>
#include <LittleFS.h>

// ================== НАСТРОЙКИ ==================
const char* AP_SSID = "WiFi-Setup";     // Имя точки доступа
const char* AP_PASS = "";               // Пусто = открытая сеть (без пароля)

const char* PHONE_HREF = "+79001234567";        // Для tel: (без пробелов)
const char* PHONE_SHOW = "+7 (900) 123-45-67";  // Как показывать на кнопке
// ===============================================

IPAddress apIP(192, 168, 4, 1);
DNSServer dnsServer;
ESP8266WebServer server(80);

void handlePage() {
  File file = LittleFS.open("/index.html", "r");
  if (!file) {
    server.send(404, "text/plain", "index.html not found. Upload LittleFS data.");
    return;
  }

  String html = file.readString();
  file.close();

  html.replace("{{PHONE_HREF}}", PHONE_HREF);
  html.replace("{{PHONE_SHOW}}", PHONE_SHOW);

  server.send(200, "text/html; charset=utf-8", html);
}

void setup() {
  Serial.begin(115200);
  Serial.println("\n=== Captive Portal ===");

  if (!LittleFS.begin()) {
    Serial.println("[ERR] LittleFS mount failed!");
    return;
  }
  Serial.println("LittleFS OK");

  WiFi.mode(WIFI_AP);
  WiFi.softAPConfig(apIP, apIP, IPAddress(255, 255, 255, 0));

  // Пустой пароль = открытая точка доступа
  bool ok = WiFi.softAP(AP_SSID, AP_PASS);
  Serial.println(ok ? "AP started (OPEN)" : "AP FAILED");

  Serial.print("AP IP: "); Serial.println(WiFi.softAPIP());

  dnsServer.start(53, "*", apIP);

  server.onNotFound(handlePage);
  server.on("/", handlePage);
  server.begin();

  Serial.println("Ready. Connect to WiFi.");
}

void loop() {
  dnsServer.processNextRequest();
  server.handleClient();
}
}
